"""Browser dashboard for creating and monitoring local Radar runs."""

from __future__ import annotations

from collections.abc import Iterable
from html import escape

from .keywords import is_searchable_keyword


def dashboard_html(communities: Iterable[str], keywords: Iterable[str] = ()) -> str:
    """Return the self-contained local task page.

    The page intentionally has no external assets or CDN dependencies so it
    continues to work when the report is being generated on a restricted
    company network.
    """
    community_count = len(tuple(communities))
    community_names = tuple(dict.fromkeys(str(item).strip().removeprefix("r/") for item in communities if str(item).strip()))
    valid_keywords = tuple(dict.fromkeys(str(term).strip() for term in keywords if is_searchable_keyword(term)))
    keyword_count = len(valid_keywords)
    community_preview = "、".join(f"r/{escape(item)}" for item in community_names[:4]) or "未加载"
    keyword_preview = "、".join(escape(item) for item in valid_keywords[:10]) or "运行时由问题自动扩展"
    return """<!doctype html>
<html lang="zh-CN">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Opportunity Radar · 采集任务</title>
  <style>
    :root{--ink:#29241f;--muted:#766d63;--line:#e4ddd4;--paper:#fffdfa;--canvas:#f4f0ea;--accent:#c95c2c;--accent-dark:#943b20;--green:#39745a;--shadow:0 20px 55px rgba(61,47,32,.10)}
    *{box-sizing:border-box} body{margin:0;background:radial-gradient(circle at 12% -10%,#fff7ed 0,#f4f0ea 42%,#eee8df 100%);color:var(--ink);font:14px/1.55 system-ui,-apple-system,"Segoe UI",sans-serif}
    .shell{max-width:1120px;margin:0 auto;padding:38px 24px 64px}.hero{display:flex;justify-content:space-between;align-items:flex-end;gap:24px;margin-bottom:26px}.eyebrow{color:var(--accent);font-size:11px;font-weight:800;letter-spacing:.16em;text-transform:uppercase}.hero h1{font:700 clamp(31px,5vw,46px)/1.05 Georgia,serif;margin:8px 0 10px;letter-spacing:-.025em}.hero p{color:var(--muted);margin:0;max-width:620px}.hero-mark{width:74px;height:74px;border:1px solid #cfbda9;border-radius:50%;display:grid;place-items:center;color:var(--accent-dark);font:700 26px Georgia,serif;background:#fffaf3;box-shadow:0 8px 25px #956f3f1c}.panel{background:rgba(255,253,250,.94);border:1px solid var(--line);border-radius:20px;box-shadow:var(--shadow);padding:25px}.panel-title{display:flex;align-items:baseline;justify-content:space-between;gap:15px;margin-bottom:19px}.panel-title h2{font-size:18px;margin:0}.panel-title p{color:var(--muted);font-size:12px;margin:0}.form-grid{display:grid;grid-template-columns:1.25fr .9fr;gap:22px}.field{min-width:0}.field-title{display:block;font-weight:750;margin-bottom:9px}.date-row{display:grid;grid-template-columns:1fr 1fr;gap:10px}.date-row input,select{width:100%;padding:11px 12px;border:1px solid #d8d0c6;border-radius:10px;background:#fff;color:var(--ink);font:inherit}.presets{display:flex;flex-wrap:wrap;gap:7px;margin-bottom:10px}.preset{padding:7px 11px;border:1px solid #ded5ca;border-radius:999px;background:#f5f0e9;color:#665d53;cursor:pointer}.preset:hover,.preset.active{border-color:#d58b68;background:#fff1e7;color:var(--accent-dark)}.helper{color:var(--muted);font-size:12px;margin:8px 0 0}.communities{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:9px}.community-option{display:grid;grid-template-columns:auto 1fr;column-gap:8px;row-gap:1px;align-items:center;border:1px solid #e2dbd2;border-radius:11px;padding:10px 11px;cursor:pointer;background:#fff}.community-option:hover{border-color:#d9a486}.community-option input{accent-color:var(--accent);width:16px;height:16px;grid-row:span 2}.community-option span{font-weight:700}.community-option small{color:var(--muted);font-size:11px}.engine{border:1px solid #e2dbd2;border-radius:11px;padding:12px;background:#fcfaf7}.engine strong{display:block}.engine span{color:var(--muted);font-size:12px}.actions{display:flex;align-items:center;gap:14px;flex-wrap:wrap;margin-top:23px;padding-top:19px;border-top:1px solid #eee7df}.primary{border:0;border-radius:10px;padding:12px 18px;background:var(--accent);color:#fff;font-weight:750;cursor:pointer;box-shadow:0 6px 15px #b9512a2e}.primary:hover{background:var(--accent-dark)}.primary:disabled{opacity:.55;cursor:not-allowed;box-shadow:none}.notice{color:var(--muted);font-size:13px}.notice.error{color:#a23a32}.runs{margin-top:30px}.runs-head{display:flex;justify-content:space-between;align-items:baseline;gap:15px;margin-bottom:11px}.runs-head h2{font-size:19px;margin:0}.runs-head span{color:var(--muted);font-size:12px}.run-list{display:grid;gap:12px}.run-card{background:rgba(255,253,250,.95);border:1px solid var(--line);border-radius:15px;padding:17px 18px}.run-top{display:flex;justify-content:space-between;align-items:flex-start;gap:15px}.run-id{font-weight:800;letter-spacing:.01em}.run-meta{color:var(--muted);font-size:12px;margin-top:3px}.status{white-space:nowrap;border-radius:999px;padding:4px 9px;font-size:11px;font-weight:750;background:#eee8df;color:#75695d}.status.running,.status.queued{background:#fff0df;color:#a34d23}.status.completed{background:#e4f1e8;color:var(--green)}.status.failed{background:#f8e4e0;color:#a23a32}.progress-wrap{margin:13px 0 8px}.progress-line{height:9px;background:#ebe4db;border-radius:99px;overflow:hidden}.progress-fill{height:100%;border-radius:inherit;background:linear-gradient(90deg,#d9783e,#c44f2d);transition:width .35s ease}.progress-fill.complete{background:linear-gradient(90deg,#5b9b78,#39745a)}.progress-label{display:flex;justify-content:space-between;color:var(--muted);font-size:12px;margin-top:5px}.run-counts{display:flex;flex-wrap:wrap;gap:7px 16px;color:#5c544b;font-size:12px;margin-top:7px}.run-counts b{color:var(--ink)}.run-bottom{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;margin-top:13px;padding-top:11px;border-top:1px solid #eee8df}.links{display:flex;gap:12px;flex-wrap:wrap}.links a{color:var(--accent-dark);font-weight:750;text-decoration:none}.links a:hover{text-decoration:underline}.retry{border:1px solid #ddc7b7;background:#fff7ef;color:var(--accent-dark);border-radius:8px;padding:6px 10px;cursor:pointer}.failure{color:#a23a32;font-size:12px;max-width:620px}.retry-note{color:#936a2e;font-size:12px;max-width:620px}.empty{border:1px dashed #d7cec3;border-radius:13px;padding:24px;text-align:center;color:var(--muted);background:#fffaf5}@media(max-width:760px){.shell{padding:25px 14px 45px}.hero{align-items:flex-start}.hero-mark{display:none}.form-grid{grid-template-columns:1fr}.communities{grid-template-columns:1fr}.date-row{grid-template-columns:1fr 1fr}.panel{padding:18px}.run-top{display:block}.status{display:inline-block;margin-top:9px}}
    .question{min-height:112px;resize:vertical;width:100%;padding:14px;border:1px solid #d8d0c6;border-radius:12px;background:#fff;color:var(--ink);font:inherit;line-height:1.6}.examples{display:flex;flex-wrap:wrap;gap:7px;margin-top:10px}.example{padding:7px 10px;border:1px solid #ded5ca;border-radius:999px;background:#f5f0e9;color:#665d53;cursor:pointer;font-size:12px}.example:hover{border-color:#d58b68;background:#fff1e7;color:var(--accent-dark)}.search-method{display:grid;gap:8px}.method-step{display:flex;gap:10px;align-items:flex-start;padding:10px 11px;border:1px solid #e2dbd2;border-radius:11px;background:#fff}.method-step b{display:grid;place-items:center;width:22px;height:22px;border-radius:50%;background:#fff0e3;color:var(--accent-dark);font-size:12px;flex:none}.method-step span{color:var(--muted);font-size:12px}.library-summary{display:flex;flex-wrap:wrap;gap:8px;margin-top:12px}.library-pill{padding:7px 10px;border:1px solid #e4d9ce;border-radius:999px;background:#fffaf5;color:#695e52;font-size:12px}.library-detail{margin-top:10px;border-top:1px solid #eee7df;padding-top:9px;color:var(--muted);font-size:12px}.library-detail summary{cursor:pointer;color:var(--accent-dark);font-weight:700}.schedule-panel{margin-top:18px}.schedule-form{display:grid;grid-template-columns:1.8fr .8fr .8fr 1fr auto;gap:9px;align-items:center}.schedule-form input,.schedule-form select{width:100%;padding:10px 11px;border:1px solid #d8d0c6;border-radius:9px;background:#fff;font:inherit}.secondary{border:1px solid #d5b39e;border-radius:10px;padding:10px 14px;background:#fff7ef;color:var(--accent-dark);font-weight:700;cursor:pointer}.schedule-list{display:grid;gap:8px;margin-top:13px}.schedule-item{border-top:1px solid #eee8df;padding-top:10px;display:flex;justify-content:space-between;gap:12px;align-items:center}.schedule-meta{color:var(--muted);font-size:12px}.schedule-actions{display:flex;gap:7px}.schedule-actions button{border:1px solid #ded0c4;border-radius:7px;background:#fff;padding:5px 8px;color:#6e5e53;cursor:pointer}.cancel{border:1px solid #e2a695;border-radius:8px;padding:6px 11px;background:#fff3ef;color:#a23a32;font-weight:750;cursor:pointer}.cancel:hover{background:#fbe1da}.cancel:disabled{opacity:.6;cursor:wait}@media(max-width:900px){.schedule-form{grid-template-columns:1fr 1fr 1fr}.schedule-form .secondary{grid-column:span 3}}@media(max-width:760px){.schedule-form{grid-template-columns:1fr 1fr}.schedule-form .secondary{grid-column:span 2}}
    .delete{border:1px solid #d8c9bf;border-radius:8px;padding:6px 10px;background:#fff;color:#6e5e53;cursor:pointer}.delete:hover{border-color:#b99580;background:#fff1e8}.delete:disabled{opacity:.6;cursor:wait}
  </style>
</head>
<body>
  <main class="shell">
    <header class="hero">
      <div><div class="eyebrow">Local research workbench</div><h1>Opportunity Radar</h1><p>输入你想了解的柴油皮卡改装问题，系统会自动扩展检索词、发现相关社区，并输出中文 VOC 分析。</p></div>
      <div class="hero-mark" aria-hidden="true">OR</div>
    </header>
    <section class="panel">
      <div class="panel-title"><h2>你想了解什么？</h2><p>同一时间只运行一个任务，避免 Chrome 会话冲突</p></div>
      <div class="form-grid">
      <div class="field"><label class="field-title" for="research-question">研究问题</label><textarea id="research-question" class="question" placeholder="例如：我想了解 Duramax 拖挂时的高温和排气改装痛点"></textarea><div class="examples"><button class="example" type="button" data-question="近一年柴油皮卡拖挂时的高温问题有哪些产品机会？">拖挂高温问题</button><button class="example" type="button" data-question="EGR cooler 现有产品最常见的安装和可靠性问题是什么？">EGR cooler 方案</button><button class="example" type="button" data-question="Cummins 用户最近在讨论哪些新的改装需求？">Cummins 新需求</button></div><p class="helper">可以用中文或英文描述；系统会自动生成平台、部件、场景、故障和解决方案检索词。</p></div>
      <div class="field"><label class="field-title">时间范围</label><div class="presets"><button class="preset" data-days="30" type="button">最近30天</button><button class="preset active" data-days="90" type="button">最近90天</button><button class="preset" data-days="180" type="button">最近180天</button><button class="preset" data-days="365" type="button">最近365天</button></div><div class="date-row"><input id="start" type="date" aria-label="开始日期"><input id="end" type="date" aria-label="结束日期"></div><p class="helper">可直接修改日期，范围最长365个自然日，结束日期不能晚于今天。</p></div>
        <div class="field"><label class="field-title" for="depth">采集深度</label><select id="depth"><option value="quick">快速 · 30 篇/社区</option><option value="standard">标准 · 80 篇/社区</option><option value="deep">深度 · 150 篇/社区</option><option value="complete" selected>完整 · 按日期边界采完</option></select><p class="helper">完整模式不设项目数量上限；会持续到日期边界或 Reddit 不再返回下一页，并保留实际覆盖情况。</p></div>
        <div class="field"><span class="field-title">系统会如何搜索</span><div class="search-method"><div class="method-step"><b>1</b><div><strong>理解你的问题</strong><span>识别柴油平台、改装部件、使用场景、故障和用户目标。</span></div></div><div class="method-step"><b>2</b><div><strong>全站检索并扩词</strong><span>先搜索基础词，再从有效帖子和评论中发现新表达和相关社区。</span></div></div><div class="method-step"><b>3</b><div><strong>清洗后做 VOC 分析</strong><span>过滤语法碎片和无关内容，按社区→话题→证据生成报告。</span></div></div></div><div class="library-summary"><span class="library-pill">${community_count} 个种子社区（后台使用）</span><span class="library-pill">${keyword_count} 条有效搜索概念</span><span class="library-pill">社区与词库自动沉淀</span><span class="library-pill">最终只展示有证据的关键社区</span></div><details class="library-detail"><summary>查看本轮后台检索底座（摘要）</summary><div class="helper">种子社区：${community_preview}</div><div class="helper">已有有效概念：${keyword_preview}${keyword_count>10?' 等':''}</div><div class="helper">实际运行时会以你的问题为主，并从有效帖子继续扩展新词和新社区。</div></details></div>
        <div class="field"><label class="field-title" for="analysis-engine">分析方式</label><select id="analysis-engine"><option value="deepseek" selected>Higress DeepSeek · 中文 VOC（推荐）</option><option value="codex">本机 Codex · 中文 VOC</option></select><p class="helper">采集仍由 OpenCLI 完成；DeepSeek 只接收已保存的帖子和评论，不访问 Reddit 页面。</p></div>
      </div>
      <div class="actions"><button id="start-run" class="primary" type="button">开始采集</button><span id="message" class="notice" role="status"></span></div>
    </section>
    <section class="panel schedule-panel"><div class="panel-title"><h2>定时任务</h2><p>服务保持运行时自动执行；也可用 scripts/register-schedule.ps1 注册 Windows 任务</p></div><div class="schedule-form"><input id="schedule-name" placeholder="任务名称，例如：每周柴油VOC扫描"><select id="schedule-frequency"><option value="daily">每天</option><option value="weekly" selected>每周</option><option value="monthly">每月</option></select><input id="schedule-time" type="time" value="09:00"><select id="schedule-window"><option value="30">滚动最近30天</option><option value="90" selected>滚动最近90天</option><option value="180">滚动最近180天</option><option value="365">滚动最近365天</option></select><button id="add-schedule" class="secondary" type="button">保存定时任务</button></div><div id="schedules" class="schedule-list"><div class="empty">尚无定时任务</div></div></section>
    <section class="runs"><div class="runs-head"><h2>任务进度</h2><span>页面每 2 秒自动刷新 · 运行中不可删除，暂停/失败/完成后可删除</span></div><div id="runs" class="run-list"><div class="empty">正在读取任务记录…</div></div></section>
  </main>
  <script>
    const $=selector=>document.querySelector(selector);
    const today=()=>{const d=new Date();return new Date(d.getFullYear(),d.getMonth(),d.getDate())};
    const iso=d=>{const y=d.getFullYear(),m=String(d.getMonth()+1).padStart(2,'0'),day=String(d.getDate()).padStart(2,'0');return `${y}-${m}-${day}`};
    const esc=value=>String(value??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
    const num=value=>Number(value||0).toLocaleString('zh-CN');
    function preset(days){const end=today(),start=new Date(end);start.setDate(start.getDate()-days+1);$('#start').value=iso(start);$('#end').value=iso(end);document.querySelectorAll('[data-days]').forEach(b=>b.classList.toggle('active',Number(b.dataset.days)===days))}
    document.querySelectorAll('[data-days]').forEach(button=>button.addEventListener('click',()=>preset(Number(button.dataset.days))));
    preset(90);
    const stageNames={queued:'排队中',resume_queued:'等待续跑',configured:'准备中',collecting:'采集帖子列表',deep_read:'获取正文和评论',collected:'采集完成',post_analysis:'帖子分析',topic_consolidation:'社区话题归并',exported:'已完成',failed:'失败',interrupted:'已暂停，可续跑',cancelled:'已取消，可续跑'};
    const stageBounds={queued:[0,4],resume_queued:[4,6],configured:[6,10],collecting:[10,35],deep_read:[35,58],collected:[58,62],post_analysis:[62,78],topic_consolidation:[78,94],exported:[100,100],failed:[100,100]};
    const legacyProgressMessage=r=>r.progress?.message||'';
    const legacyFailures=r=>r.failures||[];
    function percent(run){if(run.status==='completed'||run.stage==='exported')return 100;const stage=run.stage||run.progress?.stage||'configured',bounds=stageBounds[stage]||[6,10],p=run.progress||{};if(Number(p.total)>0)return Math.max(bounds[0],Math.min(bounds[1],Math.round(bounds[0]+(Number(p.completed||0)/Number(p.total))*(bounds[1]-bounds[0]))));return bounds[0]}
    function label(run){return stageNames[run.stage||run.progress?.stage]||run.status||'未知'}
    function decorateRunDeleteButtons(){document.querySelectorAll('.run-card').forEach(card=>{const id=card.querySelector('.run-id')?.textContent?.trim();const status=card.querySelector('.status')?.className||'';const bottom=card.querySelector('.run-bottom');if(!id||!bottom||/running|queued/.test(status)||bottom.querySelector('[data-delete-run]'))return;const button=document.createElement('button');button.className='delete';button.type='button';button.dataset.deleteRun=id;button.textContent='删除任务';bottom.appendChild(button)})}
    document.addEventListener('click',async event=>{const button=event.target.closest('[data-delete-run]');if(!button)return;const runId=button.dataset.deleteRun;if(!window.confirm(`确定删除任务 ${runId}？该任务的本地原始数据、检查点和报告将一并删除，代码及词库不受影响。`))return;button.disabled=true;const response=await fetch(`/api/runs/${encodeURIComponent(runId)}`,{method:'DELETE'});const result=await response.json().catch(()=>({}));$('#message').className=response.ok?'notice':'notice error';$('#message').textContent=response.ok?'任务已删除':(result.message||'删除任务失败');refresh()});
    document.addEventListener('click',async event=>{const button=event.target.closest('[data-cancel-run]');if(!button)return;const runId=button.dataset.cancelRun;if(!window.confirm(`确定取消任务 ${runId}？已保存的帖子和检查点会保留，可之后续跑。`))return;button.disabled=true;button.textContent='正在取消…';const response=await fetch(`/api/runs/${encodeURIComponent(runId)}/cancel`,{method:'POST'});const result=await response.json().catch(()=>({}));$('#message').className=response.ok?'notice':'notice error';$('#message').textContent=response.ok?'任务已取消，检查点已保留':(result.message||'取消任务失败');refresh()});
    new MutationObserver(decorateRunDeleteButtons).observe(document.querySelector('#runs'),{childList:true});
    function renderRun(run){const pct=percent(run),active=run.status==='running'||run.status==='queued',counts=run.counts||{},scope=run.collection_scope||{},start=run.start_date||scope.start_date||'',end=run.end_date||scope.end_date||'',depth=run.depth||scope.depth||'',question=run.research_question||'柴油皮卡改装市场扫描';const progress=run.progress||{},failures=legacyFailures(run),failureText=failures.slice(0,2).map(item=>esc(item.message||item.stage)).join('；');const issue=run.status==='failed'||run.status==='interrupted'?`<div class="failure">${failureText||'任务已暂停，可从检查点续跑。'}</div>`:failures.length?`<div class="retry-note">已记录 ${num(failures.length)} 条可重试记录，任务仍在继续。</div>`:'';const links=run.status==='completed'?`<div class="links"><a href="/runs/${encodeURIComponent(run.run_id)}/report" target="_blank">打开 HTML 报告</a><a href="/runs/${encodeURIComponent(run.run_id)}/workbook" download>下载 Excel</a><a href="/api/runs/${encodeURIComponent(run.run_id)}/analysis" download>下载 JSON</a></div>`:(run.status==='failed'||run.status==='interrupted'||run.status==='incomplete')?`<button class="retry" data-resume="${esc(run.run_id)}" type="button">续跑任务</button>`:'';const controls=active?`<button class="cancel" data-cancel-run="${esc(run.run_id)}" type="button">取消任务</button>`:links;return `<article class="run-card"><div class="run-top"><div><div class="run-id">${esc(run.run_id)}</div><div class="run-meta">${esc(question)} · ${esc(start)} → ${esc(end)} · ${esc(depth)}</div></div><span class="status ${active?'running':esc(run.status)}">${esc(label(run))}</span></div><div class="progress-wrap"><div class="progress-line"><div class="progress-fill ${run.status==='completed'?'complete':''}" style="width:${pct}%"></div></div><div class="progress-label"><span>${esc(progress.message||legacyProgressMessage(run)||label(run))}</span><b>${pct}%</b></div></div><div class="run-counts"><span>扫描 <b>${num(counts.candidate_count)}</b></span><span>深读 <b>${num(counts.deep_read_count)}</b></span><span>分析 <b>${num(counts.analyzed_posts)}</b></span><span>话题 <b>${num(counts.topic_count)}</b></span><span>失败 <b>${num(counts.failure_count)}</b></span></div><div class="run-bottom">${issue}${controls}</div></article>`}
    async function refresh(){try{const response=await fetch('/api/runs',{cache:'no-store'});const data=await response.json();const runs=data.runs||[];$('#runs').innerHTML=runs.length?runs.map(renderRun).join(''):'<div class="empty">尚无任务。选择时间范围后点击“开始采集”。</div>';const active=runs.some(run=>run.status==='running'||run.status==='queued');$('#start-run').disabled=active;document.querySelectorAll('[data-resume]').forEach(button=>button.addEventListener('click',()=>resume(button.dataset.resume)));const scheduleResponse=await fetch('/api/schedules',{cache:'no-store'});const schedules=(await scheduleResponse.json()).schedules||[];$('#schedules').innerHTML=schedules.length?schedules.map(schedule=>`<div class="schedule-item"><div><b>${esc(schedule.name)}</b><div class="schedule-meta">${schedule.frequency} · ${schedule.at_time} · 最近${schedule.window_days}天 · 下次 ${esc(schedule.next_run_at||'')}</div>${schedule.last_error?`<div class="failure">${esc(schedule.last_error)}</div>`:''}</div><div class="schedule-actions"><button data-toggle="${esc(schedule.schedule_id)}">${schedule.enabled?'暂停':'启用'}</button><button data-delete="${esc(schedule.schedule_id)}">删除</button></div></div>`).join(''):'<div class="empty">尚无定时任务</div>';document.querySelectorAll('[data-toggle]').forEach(button=>button.onclick=()=>scheduleAction(button.dataset.toggle,'toggle'));document.querySelectorAll('[data-delete]').forEach(button=>button.onclick=()=>scheduleAction(button.dataset.delete,'delete'))}catch(error){$('#message').className='notice error';$('#message').textContent='本地服务暂时无响应，请确认窗口中的 radar serve 仍在运行。'}}
    async function resume(runId){$('#message').className='notice';$('#message').textContent='正在续跑…';const response=await fetch(`/api/runs/${encodeURIComponent(runId)}/resume`,{method:'POST'});const result=await response.json();$('#message').textContent=response.ok?'已重新加入任务队列':(result.message||'续跑失败');refresh()}
    document.querySelectorAll('[data-question]').forEach(button=>button.addEventListener('click',()=>{$('#research-question').value=button.dataset.question;$('#research-question').focus()}));
    $('#start-run').addEventListener('click',async()=>{const start=$('#start').value,end=$('#end').value,question=$('#research-question').value.trim(),message=$('#message');if(!question){message.className='notice error';message.textContent='请先输入你想了解的问题。';$('#research-question').focus();return}if(!start||!end){message.className='notice error';message.textContent='请先选择开始和结束日期。';return}const span=(new Date(`${end}T00:00:00`)-new Date(`${start}T00:00:00`))/86400000+1;if(span<1||span>365){message.className='notice error';message.textContent='时间范围必须为 1 至 365 个自然日。';return}const payload={research_question:question,start_date:start,end_date:end,depth:$('#depth').value,analysis_engine:$('#analysis-engine').value};$('#start-run').disabled=true;message.className='notice';message.textContent='正在理解问题并创建任务…';try{const response=await fetch('/api/runs',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const result=await response.json();message.className=response.ok?'notice':'notice error';message.textContent=response.ok?'任务已启动，系统会自动扩展检索词并更新进度':(result.message||'创建任务失败')}catch(error){message.className='notice error';message.textContent='无法连接本地服务。'}refresh()});
    async function scheduleAction(id,action){const response=action==='delete'?await fetch(`/api/schedules/${encodeURIComponent(id)}`,{method:'DELETE'}):await fetch(`/api/schedules/${encodeURIComponent(id)}/toggle`,{method:'POST'});if(!response.ok){const data=await response.json();$('#message').textContent=data.message||'定时任务操作失败'}refresh()}
    $('#add-schedule').addEventListener('click',async()=>{const payload={name:$('#schedule-name').value||'柴油皮卡VOC滚动扫描',research_question:$('#research-question').value.trim(),frequency:$('#schedule-frequency').value,at_time:$('#schedule-time').value,window_days:Number($('#schedule-window').value),depth:$('#depth').value,analysis_engine:$('#analysis-engine').value};const response=await fetch('/api/schedules',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const data=await response.json();$('#message').className=response.ok?'notice':'notice error';$('#message').textContent=response.ok?'定时任务已保存':(data.message||'定时任务保存失败');refresh()});
    refresh();setInterval(refresh,2000);
  </script>
  <script>
    // Capture run actions before the legacy delegated handlers so a slow or
    // disconnected browser always receives visible feedback instead of an
    // unhandled promise rejection.
    document.addEventListener('click',async event=>{const button=event.target.closest?.('[data-delete-run],[data-cancel-run]');if(!button)return;event.preventDefault();event.stopImmediatePropagation();const runId=button.dataset.deleteRun||button.dataset.cancelRun;const isDelete=Boolean(button.dataset.deleteRun);let accepted=true;try{accepted=typeof window.confirm!=='function'||window.confirm(isDelete?`确定删除任务 ${runId}？该任务的本地原始数据、检查点和报告将一并删除，代码及词库不受影响。`:`确定取消任务 ${runId}？已保存的帖子和检查点会保留，可之后续跑。`)}catch(_error){}if(!accepted)return;const message=document.querySelector('#message');const originalText=button.textContent;button.disabled=true;button.textContent=isDelete?'正在删除…':'正在取消…';message.className='notice';message.textContent=(isDelete?'正在删除任务':'正在取消任务')+'，请稍候…';try{const response=await fetch(isDelete?`/api/runs/${encodeURIComponent(runId)}`:`/api/runs/${encodeURIComponent(runId)}/cancel`,{method:isDelete?'DELETE':'POST'});const result=await response.json().catch(()=>({}));if(!response.ok)throw new Error(result.message|| (isDelete?'删除请求失败':'取消请求失败'));message.className='notice';message.textContent=isDelete?'任务已删除':'任务已取消，检查点已保留';await refresh()}catch(error){message.className='notice error';message.textContent=(isDelete?'删除请求失败':'取消请求失败')+`：${error.message||'本地服务无响应'}`;button.disabled=false;button.textContent=originalText}},true);
  </script>
</body>
</html>""".replace("${community_count}", str(community_count)).replace("${keyword_count}", str(keyword_count))
